tool_input.command:
mkdir -p .playwright && cat > .playwright/check.mjs <<'EOF'
import { chromium } from '@playwright/test';
const base = `http://localhost:${process.env.PORT}`;
const b = await chromium.launch();
const errs = [];
async function sq(page, s){ const r = await page.locator(`[data-square="${s}"]`).boundingBox(); return [r.x+r.width/2, r.y+r.height/2]; }
async function click(page, s){ const [x,y]=await sq(page,s); await page.mouse.click(x,y); }
const puzzles = await (await fetch(base+'/puzzles.json')).json();
const ctx = await b.newContext({ viewport:{width:390,height:800}, hasTouch:true, colorScheme:'dark' });
const page = await ctx.newPage();
page.on('console', m=>{ if(m.type()==='error'||m.type()==='warning') errs.push(m.text()); });
page.on('pageerror', e=>errs.push(String(e)));
for (const p of puzzles) {
  await page.goto(`${base}/?puzzle=${p.id}`);
  await page.waitForSelector('[data-square]');
  for (let i=0;i<p.solution.length;i+=2) {
    const u=p.solution[i];
    await click(page,u.slice(0,2)); await click(page,u.slice(2,4));
    if (u.length>4) await page.locator(`[data-testid=promotion] [data-piece=${u[4]}]`).click();
    if (i+1<p.solution.length) await page.waitForTimeout(700);
  }
  const ok = await page.getByTestId('puzzle-solved').isVisible();
  const sw = await page.evaluate(()=>[document.documentElement.scrollWidth, innerWidth]);
  console.log('puzzle',p.id,ok,sw.join('/'));
}
await page.goto(base+'/');
console.log('bg dark', await page.evaluate(()=>getComputedStyle(document.body).backgroundColor));
console.log('sw play 390', await page.evaluate(()=>[document.documentElement.scrollWidth, innerWidth]));
console.log('squares', await page.locator('[data-square]').count(), 'pieces', await page.locator('[data-piece]').count());
// touch drag via CDP
const cdp = await ctx.newCDPSession(page);
const [x1,y1]=await sq(page,'e2'), [x2,y2]=await sq(page,'e4');
const tp=(x,y)=>[{x,y,id:1}];
await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:tp(x1,y1)});
for(let i=1;i<=5;i++) await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:tp(x1+(x2-x1)*i/5,y1+(y2-y1)*i/5)});
await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
console.log('touch drag e4 has piece', await page.locator('[data-square=e4] [data-piece]').count());
const l = await b.newContext({ viewport:{width:1280,height:800}, colorScheme:'light'});
const p2 = await l.newPage(); p2.on('console', m=>{ if(m.type()==='error') errs.push(m.text()); });
await p2.goto(base+'/');
console.log('bg light', await p2.evaluate(()=>getComputedStyle(document.body).backgroundColor));
console.log('sw 1280', await p2.evaluate(()=>[document.documentElement.scrollWidth, innerWidth]));
// threefold & 50-move via fen
await p2.goto(base+'/?fen=4k3/8/8/8/8/8/8/4K2R w - - 100 80');
await click(p2,'h1'); await click(p2,'h2');
console.log('50move', await p2.getByTestId('game-over').innerText().catch(()=>'none'));
await p2.goto(base+'/?fen=garbage'); console.log('bad fen ok', await p2.locator('[data-square]').count());
console.log('errors', errs);
await b.close();
EOF
(PORT=5199 npm run dev > .playwright/dev.log 2>&1 & echo $! > .playwright/dev.pid); sleep 3; PORT=5199 node .playwright/check.mjs
